{"command":"cat <<'EOF' > check_fts5.c
#include <sqlite3.h>
#include <stdio.h>

int main() {
    sqlite3 *db;
    int rc = sqlite3_open(":memory:", &db);
    if (rc != SQLITE_OK) {
        printf("Cannot open database: %s\n", sqlite3_errmsg(db));
        return 1;
    }
    rc = sqlite3_exec(db, "SELECT load_extension('fts5');", NULL, NULL, NULL);
    if (rc != SQLITE_OK) {
        printf("FTS5 not available: %s\n", sqlite3_errmsg(db));
    } else {
        printf("FTS5 is available\n");
    }
    sqlite3_close(db);
    return 0;
}
EOF
gcc check_fts5.c -lsqlite3 -o check_fts5
./check_fts5
"}

