{"command":"cat <<'EOF' > test_sqlite.go
package main

import (
	"database/sql"
	"fmt"
	_ "modernc.org/sqlite"
)

func main() {
	db, err := sql.Open("sqlite", ":memory:")
	if err != nil {
		panic(err)
	}
	_, err = db.Exec("CREATE VIRTUAL TABLE test USING fts5(content);")
	if err != nil {
		fmt.Printf("FTS5 not available: %v\n", err)
	} else {
		fmt.Println("FTS5 is available")
	}
}
EOF
go mod init test
go mod tidy
go run test_sqlite.go
"}

